function validate([bookings, n]) {
  if (!Number.isInteger(n) || n < 1 || n > 20000) return 'n is between 1 and 2 * 10^4.';
  if (!Array.isArray(bookings) || bookings.length < 1 || bookings.length > 20000) return 'bookings needs 1 to 2 * 10^4 entries.';
  for (const booking of bookings) {
    if (!Array.isArray(booking) || booking.length !== 3 || !booking.every(Number.isInteger)) return 'Each booking is [first, last, seats] of integers.';
    const [first, last, seats] = booking;
    if (first < 1 || first > last || last > n) return 'Each booking needs 1 <= first <= last <= n.';
    if (seats < 1 || seats > 10000) return 'seats is between 1 and 10^4.';
  }
  return null;
}

