function corpFlightBookings(bookings, n) {
  const totals = [];
  for (let flight = 1; flight <= n; flight++) {
    let sum = 0;
    for (const booking of bookings) {
      if (booking[0] <= flight && flight <= booking[1]) sum += booking[2];
    }
    totals.push(sum);
  }
  return totals;
}

