function generate(rand, size) {
  const large = size === 'large';
  const n = large ? 2000 : 1 + Math.floor(rand() * 8);
  const count = large ? 2000 : 1 + Math.floor(rand() * 6);
  const maxSeats = large ? 10000 : (rand() < 0.5 ? 5 : 10000);
  const bookings = [];
  for (let i = 0; i < count; i++) {
    const a = 1 + Math.floor(rand() * n);
    const b = 1 + Math.floor(rand() * n);
    bookings.push([Math.min(a, b), Math.max(a, b), 1 + Math.floor(rand() * maxSeats)]);
  }
  return [bookings, n];
}
